ROOT=Path(__file__).resolve().parents[1];CACHE=ROOT/'data'/'source_cache';OUT=ROOT/'data'/'seed'/'enforcement_law.py'
FA2A=str.maketrans('۰۱۲۳۴۵۶۷۸۹','0123456789');A2FA=str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹')
def strip_md(s):
 s=re.sub(r'\[([^]]+)\]\([^)]+\)',r'\1',s);return s.replace('**','').replace('__','').replace('\\-','-').strip()
def clean(s):
 repl={'ي':'ی','ك':'ک','ة':'ه','\ufeff':'','\u00ad':'','\u200e':'‌','\u200f':'‌','‎':'‌','‏':'‌','آئین':'آیین','هیات':'هیأت','مسوول':'مسئول','موسسات':'مؤسسات','موسسه':'مؤسسه','میباشد':'می‌باشد','میشود':'می‌شود','میشوند':'می‌شوند','میگردد':'می‌گردد','میکند':'می‌کند','میتواند':'می‌تواند','می نماید':'می‌نماید','می شود':'می‌شود','می گردد':'می‌گردد','می باشد':'می‌باشد','نمی باشد':'نمی‌باشد','بموجب':'به موجب','بعهده':'به عهده','بعمل':'به عمل','بوسیله':'به وسیله','بمحکوم':'به محکوم','بدادگاه':'به دادگاه','بقسمت':'به قسمت','بمرجع':'به مرجع','بمیزان':'به میزان','بامضاء':'به امضاء','بمهر':'به مهر','بتعداد':'به تعداد','بعلاوه':'به علاوه','باقتضای':'به اقتضای','بشخص':'به شخص','باشخاص':'به اشخاص','بامانت':'به امانت','لازم الاجرا':'لازم‌الاجرا','محکوم علیه':'محکوم‌علیه','محکوم له':'محکوم‌له','محکوم به':'محکوم‌به','ممنوع الخروج':'ممنوع‌الخروج','حق الوکاله':'حق‌الوکاله','پیش قسط':'پیش‌قسط','غیر منقول':'غیرمنقول','ذینفع':'ذی‌نفع','وصیت نامه':'وصیت‌نامه','موصی له':'موصی‌له','صورت مجلس':'صورت‌جلسه','صورتمجلس':'صورت‌جلسه'}
 for a,b in repl.items():s=s.replace(a,b)
 s=re.sub(r'\s*\((?:اصلاحی|الحاقی|منسوخه?)[^)]*\)\s*[–-]?','',s)
 s=re.sub(r'‌+','‌',s);s=re.sub(r'[ \t]*‌[ \t]*','‌',s);s=re.sub(r'(^|\n)‌',r'\1',s);s=re.sub(r'([)\]،؛:.])‌',r'\1 ',s)
 s=re.sub(r'[ \t]+',' ',s);s=re.sub(r' *\n *','\n',s);s=re.sub(r'\n{3,}','\n\n',s);return s.translate(A2FA).strip()
def parse(path,wanted):
 arts={};cur=None
 for raw in path.read_text().splitlines():
  line=strip_md(raw);m=re.match(r'^(?:\([^)]*\)\s*)?ماده\s*([۰-۹0-9]+)(?:\s*\([^)]*\))?\s*[ـ–-]\s*(.*)$',line.lstrip('‌ #'))
  if m:
   n=int(m.group(1).translate(FA2A));cur=n if n in wanted and n not in arts else None
   if cur:arts[cur]=[m.group(2)] if m.group(2) else []
   continue
  if cur is None or not line:continue
  if line.startswith('#') or re.match(r'^(فصل|مبحث|باب)\s',line):continue
  if line.startswith(('قانون فوق مشتمل','این آیین‌نامه به پیشنهاد','سید ابراهیم','رئیس مجلس','* * *','انتهای پیام')):cur=None;continue
  if 'https://' in line or '](http' in line:continue
  arts[cur].append(line)
 miss=sorted(wanted-set(arts))
 if miss:raise ValueError(f'{path.name}: {miss}')
 return {n:clean('\n'.join(arts[n])) for n in sorted(wanted)}

